/** Names that draw the same icon as another name. */
const SAME = {
	prohibited: "slash",
	dataBar: "chart",
	textBullet: "list",
	brainCircuit: "brain",
	split: "fork",
};

const SMALL = new Set(["terminal","pr","merge"]);

/** The SVG of an icon by name, exactly as Fluent ships it, or undefined. */
export function svgOf(name) {
	const key = SAME[name] ?? name;
	const d = PATHS[key];
	if (!d) {
		return undefined;
	}
	const s = SMALL.has(key) ? 20 : 24;
	return `<svg xmlns="http://www.w3.org/2000/svg" width="${s}" height="${s}" viewBox="0 0 ${s} ${s}"><path d="${d}"/></svg>`;
}

export const ICON_NAMES = [...Object.keys(PATHS), ...Object.keys(SAME)];

export const ICONS = Object.fromEntries(ICON_NAMES.map(n => [n, svgOf(n)]));
